"""Core data contracts and specifications for the Solution SDK."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import TypeAlias

from seedwork.domain.types import JsonDict

# Strictly-typed HTTP request body: JSON object, raw string (XML/SOAP), bytes, or None.
HttpRequestBody: TypeAlias = JsonDict | str | bytes | None


@dataclass(frozen=True, kw_only=True)
class RequestSpec:
    """Immutable HTTP request specification generated by solution connectors.

    The platform connection manager binds this specification with tenant credentials,
    rate limiters, token rotators, and mTLS certificates before dispatching.
    """

    method: str
    path: str
    headers: dict[str, str] = field(default_factory=dict)
    params: dict[str, str] = field(default_factory=dict)
    body: HttpRequestBody = None
